def main():
    master=ROOT/'data/master/officers';path=master/'assessments.json'
    assessments=json.loads(path.read_text(encoding='utf-8'))
    roster={r['external_id']:r for r in json.loads((ROOT/'data/derived/officers/officers_1546.json').read_text(encoding='utf-8'))['officers']}
    before={q:a for q,a in assessments.items() if a.get('cohort') in ('major_60','next_60')}
    digest=hashlib.sha256(json.dumps(before,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
    selection_path=master/'third_60_selection.json'
    if selection_path.exists() and json.loads(selection_path.read_text(encoding='utf-8'))['previous_120_sha256']!=digest:raise ValueError('Earlier assessments changed')
    source_map={s['id']:s for s in json.loads((master/'sources.json').read_text(encoding='utf-8'))}
    for key,(title,url) in SOURCES.items():source_map[key]={'id':key,'title':title,'url':url,'accessed':'2026-09-12','use':'短い参照事項とリンク。数値は編集評価で、原文・画像の転載なし。'}
    selected=[]
    for rank,line in enumerate(ROWS.splitlines(),1):
        q,name,refs,evidence,items=line.split('|')
        assert q in roster and (q not in assessments or assessments[q].get('cohort')=='third_60'),name
        assert all(ref in source_map for ref in refs.split(',')),refs
        scores={};reasons={};basis={};confidence={}
        for key,item in zip(KEYS,items.split(';'),strict=True):
            kind,value,reason=item.split(':',2);scores[key]=int(value);reasons[key]=reason;basis[key]=TYPES[kind];confidence[key]='limited_evidence' if kind in 'PNF' else 'editorial_estimate'
        assessments[q]={'status':'editorial_draft','cohort':'third_60','selection_rank':rank,'basis':'lifetime','scores':scores,'source_refs':refs.split(','),'evidence':evidence,'score_reasons':reasons,'score_basis':basis,'score_confidence':confidence,'confidence':'provisional','score_policy':'participation_standard_v2','caveat':'生涯の業績からのゲーム用比較値。参加が確認でき目立つ失策がない任務は標準遂行と解釈。成否材料なし・失敗のみは参照範囲での判断で、史料の完全な網羅を意味しない。未誕生者の点数は開始時に出仕できることを意味しない。','score_method':'1〜30点・1点刻み。成否材料なし12前後、失敗のみ5前後。参加のみは規模・戦域・責任を評価し、明確な功績・失敗は個別に加減。掲載順は今回60人内の編集上の知名度目安であり統計順位ではない。'}
        selected.append({'external_id':q,'display_name':roster[q]['display_name'],'selection_rank':rank})
    assert len(selected)==60 and len({r['external_id'] for r in selected})==60
    assert len(before)==120
    for filename,value in [('assessments.json',assessments),('sources.json',list(source_map.values())),('third_60_selection.json',{'selection':'現在の名簿の未評価者から知名度を目安に60人を編集選定。開始時未誕生者も含む。今回60人内の掲載順であり測定された人気順位や能力順位ではない。','previous_120_sha256':digest,'officers':selected})]:
        (master/filename).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('Assessed',len(selected),'new officers; total',len(assessments))
if __name__=='__main__':main()
